fix.src/queue.ts:
export function enqueue<T>(items: T[], value: T): T[] {
  return [...items, value];
}

export function dequeue<T>(items: T[]): T | undefined {
  return items[0];
}

fix.src/retry.ts:
export function shouldRetry(attempt: number, max: number): boolean {
  return attempt < max;
}

export function nextState(state: string): string {
  if (state === 'queued') return 'running';
  if (state === 'running') return 'done';
  return state;
}
